use std::{fs,process::Command};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn main(){let r="/tmp/zopro-poseidon-direct-dot";let binary=format!("{r}/native/direct-sdk");let out=Command::new("nm").args(["-S","--size-sort","--demangle",&binary]).output().unwrap();assert!(out.status.success());let symbols=String::from_utf8(out.stdout).unwrap();assert!(!symbols.contains("sparse_poseidon::dot::dot"));let selected:Vec<_>=symbols.lines().filter(|l|l.contains("sparse_poseidon")).collect();fs::write(format!("{r}/poseidon-symbols.txt"),selected.join("\n")).unwrap();let source=fs::read_to_string(format!("{r}/candidate/crates/zopro-core/src/solver/sparse_poseidon.rs")).unwrap();assert_eq!(source.matches("Fr::sum_of_products").count(),2);assert!(!source.contains("mod dot;")&&!source.contains("dot::dot"));let old:Value=serde_json::from_slice(&fs::read("/tmp/zopro-poseidon-fused-dot/codegen-audit.json").unwrap()).unwrap();assert_eq!(old["dot_body_bytes"],2861);fs::write(format!("{r}/codegen-audit.json"),serde_json::to_vec_pretty(&json!({"binary":binary,"binary_sha256":format!("{:x}",Sha256::digest(fs::read(&binary).unwrap())),"generic_dot_helper_symbol_absent":true,"direct_source_fused_call_sites":2,"previous_generic_helper_bytes":2861,"dynamic_call_count_measured":false,"no_new_cycle_profile_claimed":true,"causal_speedup_claimed":false})).unwrap()).unwrap();println!("Direct SDK: generic dot helper absent;2source fixed-width fused call sites; no speedup inferred");}
